def cheapest_with_credits(nodes, edges, start, goal):
    known = set(nodes)
    if start not in known or goal not in known:
        raise KeyError('start and goal must be nodes')
    if any(u not in known or v not in known or type(w) is not int for u, v, w in edges):
        raise ValueError('edges need known nodes and integer costs')
    distance, previous = {start: 0}, {}
    for _ in range(len(known) - 1):
        changed = False
        for u, v, weight in edges:
            if u in distance and distance[u] + weight < distance.get(v, float('inf')):
                distance[v], previous[v] = distance[u] + weight, u
                changed = True
        if not changed:
            break
    if any(u in distance and distance[u] + weight < distance.get(v, float('inf')) for u, v, weight in edges):
        raise ValueError('reachable negative cycle')
    if goal not in distance:
        return None
    path = [goal]
    while path[-1] != start:
        path.append(previous[path[-1]])
    return distance[goal], list(reversed(path))

